import { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import "../css/navbar.css";

const STORAGE_USER_KEY = "user";
const STORAGE_TOKEN_KEY = "token";

function Navbar() {
  const navigate = useNavigate();
  const location = useLocation();

  const [user, setUser] = useState(null);
  const [profileOpen, setProfileOpen] = useState(false);

  useEffect(() => {
    function loadUser() {
      try {
        setUser(
          JSON.parse(localStorage.getItem(STORAGE_USER_KEY) || "null")
        );
      } catch {
        setUser(null);
      }
    }

    loadUser();
    window.addEventListener("storage", loadUser);

    return () => {
      window.removeEventListener("storage", loadUser);
    };
  }, []);

  useEffect(() => {
    setProfileOpen(false);
  }, [location.pathname]);

  useEffect(() => {
    function handleOutsideClick(event) {
      if (!event.target.closest(".profile-menu")) {
        setProfileOpen(false);
      }
    }

    document.addEventListener("click", handleOutsideClick);

    return () => {
      document.removeEventListener("click", handleOutsideClick);
    };
  }, []);

  function isActive(path) {
    return location.pathname.replace(/\/+$/, "") === path;
  }

  function logout() {
    localStorage.removeItem(STORAGE_TOKEN_KEY);
    localStorage.removeItem(STORAGE_USER_KEY);

    setUser(null);
    setProfileOpen(false);

    navigate("/", { replace: true });
  }

  const displayName =
    user?.displayname_th ||
    user?.displayname_en ||
    user?.name ||
    "-";

  return (
    <header className="site-header">
      <button
        type="button"
        className="brand"
        aria-label="Booking CSTU Home"
        onClick={() => navigate("/homepage")}
      >
        <img
          className="brand-logo"
          src={`${process.env.PUBLIC_URL}/logo.png`}
          alt="Booking CSTU logo"
          onError={(event) => {
            event.currentTarget.style.display = "none";
          }}
        />

        <span className="brand-copy">
          <strong>CSTU ROOM BOOKING</strong>
          <small>BOOKING CSTU ROOM</small>
        </span>
      </button>

      <nav className="main-nav" aria-label="เมนูหลัก">
        <button
          type="button"
          className={`nav-link ${isActive("/homepage") ? "active" : ""}`}
          onClick={() => navigate("/homepage")}
        >
          HOME
        </button>

        <button
          type="button"
          className={`nav-link ${isActive("/mybooking") ? "active" : ""}`}
          onClick={() => navigate("/mybooking")}
        >
          MY BOOKING
        </button>

        <a
          href={`${process.env.PUBLIC_URL}/Guide.html`}
          className="nav-link"
        >
          GUIDE
        </a>

        <a
          href={`${process.env.PUBLIC_URL}/Rule.html`}
          className="nav-link"
        >
          RULE
        </a>

        <button
          type="button"
          className={`nav-link ${isActive("/review") ? "active" : ""}`}
          onClick={() => navigate("/review")}
        >
          REVIEW
        </button>

        <div className="profile-menu">
          <button
            type="button"
            id="profileButton"
            className={`nav-link profile-button ${
              profileOpen ? "profile-open" : ""
            }`}
            aria-expanded={profileOpen}
            aria-controls="profilePopup"
            onClick={() => setProfileOpen((value) => !value)}
          >
            <span>PROFILE</span>
            <span className="chevron" aria-hidden="true">
              ⌄
            </span>
          </button>

          {profileOpen && (
            <section
              id="profilePopup"
              className="profile-popup"
              aria-label="ข้อมูลผู้ใช้"
              onClick={(event) => event.stopPropagation()}
            >
              <h2>ข้อมูลผู้ใช้</h2>

              <dl className="profile-details">
                <div>
                  <dt>ชื่อ</dt>
                  <dd>{displayName}</dd>
                </div>

                <div>
                  <dt>Username</dt>
                  <dd>
                    {user?.username || user?.tu_id || user?.user_id || "-"}
                  </dd>
                </div>

                <div>
                  <dt>คณะ</dt>
                  <dd>{user?.faculty || "-"}</dd>
                </div>

                <div>
                  <dt>สาขา</dt>
                  <dd>{user?.department || user?.major || "-"}</dd>
                </div>

                <div>
                  <dt>Email</dt>
                  <dd>{user?.email || "-"}</dd>
                </div>
              </dl>

              <button
                type="button"
                id="logoutButton"
                className="button button-danger button-full"
                onClick={logout}
              >
                LOGOUT
              </button>
            </section>
          )}
        </div>
      </nav>
    </header>
  );
}

export default Navbar;
